def detach_pilots(apps, schema_editor):
    User = apps.get_model('users', 'User')
    Pilot = apps.get_model('field_jobs', 'FieldPilot')
    Job = apps.get_model('field_jobs', 'FieldJob')
    Rate = apps.get_model('field_jobs', 'PilotRate')
    Earning = apps.get_model('field_jobs', 'PilotEarning')
    alias = schema_editor.connection.alias
    ids = set(User.objects.using(alias).filter(role='piloto').values_list('pk', flat=True))
    ids.update(Job.objects.using(alias).exclude(technician=None).values_list('technician_id', flat=True))
    ids.update(Rate.objects.using(alias).values_list('pilot_id', flat=True))
    ids.update(Earning.objects.using(alias).values_list('pilot_id', flat=True))
    for user in User.objects.using(alias).filter(pk__in=ids).order_by('pk'):
        base = (user.full_name.strip() or user.email)[:150]
        name, suffix = base, 1
        while Pilot.objects.using(alias).filter(name=name).exists():
            suffix += 1
            name = f'{base[:135]} ({suffix})'
        pilot = Pilot.objects.using(alias).create(name=name, is_active=user.is_active)
        Job.objects.using(alias).filter(technician_id=user.pk).update(pilot_id=pilot.pk)
        Rate.objects.using(alias).filter(pilot_id=user.pk).update(independent_pilot_id=pilot.pk)
        Earning.objects.using(alias).filter(pilot_id=user.pk).update(independent_pilot_id=pilot.pk)
    # Keep audit authors intact, but retire every login formerly used by a pilot.
    User.objects.using(alias).filter(role='piloto').update(is_active=False, role='readonly', password='!')


